create table if not exists public.quests (id uuid primary key default gen_random_uuid(), owner_type text not null check (owner_type in ('business','fleet','enterprise','admin')), owner_id uuid, name text not null, description text, status text not null default 'draft' check (status in ('draft','active','paused','completed','archived')), start_at timestamptz, end_at timestamptz, reward_config jsonb not null default '{}'::jsonb, targeting_config jsonb not null default '{}'::jsonb, route_config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.quest_steps (id uuid primary key default gen_random_uuid(), quest_id uuid not null references public.quests(id) on delete cascade, step_order integer not null, step_type text not null check (step_type in ('arrive','scan','rate','review','evidence','checkin','visit','photo','challenge','custom')), title text not null, description text, location_id uuid, geofence_id uuid, qr_code_id uuid, required boolean not null default true, xp_reward integer not null default 0, reward_config jsonb not null default '{}'::jsonb, validation_config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique (quest_id, step_order));
create table if not exists public.quest_participation (id uuid primary key default gen_random_uuid(), quest_id uuid not null references public.quests(id) on delete cascade, user_id uuid not null, status text not null default 'started' check (status in ('started','completed','abandoned','expired')), current_step_order integer not null default 1, progress numeric(6,3) not null default 0, xp_earned integer not null default 0, reward_state jsonb not null default '{}'::jsonb, started_at timestamptz not null default now(), completed_at timestamptz, updated_at timestamptz not null default now(), unique (quest_id,user_id));
create table if not exists public.quest_step_events (id uuid primary key default gen_random_uuid(), participation_id uuid not null references public.quest_participation(id) on delete cascade, quest_step_id uuid not null references public.quest_steps(id) on delete cascade, user_id uuid not null, event_type text not null, source text, location_id uuid, geofence_event_id uuid, qr_code_id uuid, checkin_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists quests_owner_idx on public.quests(owner_type,owner_id,status);
create index if not exists quest_steps_quest_idx on public.quest_steps(quest_id,step_order);
create index if not exists quest_participation_user_idx on public.quest_participation(user_id,status);
create index if not exists quest_events_participation_idx on public.quest_step_events(participation_id,created_at desc);
create or replace function public.quest_start(p_quest_id uuid) returns public.quest_participation language plpgsql security invoker as $$ declare v public.quest_participation; begin insert into public.quest_participation(quest_id,user_id) values (p_quest_id,auth.uid()) on conflict (quest_id,user_id) do update set updated_at=now() returning * into v; return v; end $$;
create or replace function public.quest_record_step(p_participation_id uuid,p_quest_step_id uuid,p_event_type text,p_source text default null,p_metadata jsonb default '{}'::jsonb,p_location_id uuid default null,p_geofence_event_id uuid default null,p_qr_code_id uuid default null,p_checkin_id uuid default null) returns public.quest_participation language plpgsql security invoker as $$ declare v public.quest_participation; s public.quest_steps; q public.quests; n numeric; begin select * into v from public.quest_participation where id=p_participation_id and user_id=auth.uid() for update; if not found then raise exception 'Quest participation not found'; end if; select * into s from public.quest_steps where id=p_quest_step_id and quest_id=v.quest_id; if not found then raise exception 'Quest step not found'; end if; insert into public.quest_step_events(participation_id,quest_step_id,user_id,event_type,source,location_id,geofence_event_id,qr_code_id,checkin_id,metadata) values(v.id,s.id,auth.uid(),p_event_type,p_source,p_location_id,p_geofence_event_id,p_qr_code_id,p_checkin_id,coalesce(p_metadata,'{}'::jsonb)); update public.quest_participation set current_step_order=greatest(current_step_order,s.step_order+1),xp_earned=xp_earned+coalesce(s.xp_reward,0),progress=least(1.0,(s.step_order::numeric)/(greatest((select count(*) from public.quest_steps where quest_id=v.quest_id),1))),status=case when s.step_order=(select max(step_order) from public.quest_steps where quest_id=v.quest_id) then 'completed' else 'started' end,completed_at=case when s.step_order=(select max(step_order) from public.quest_steps where quest_id=v.quest_id) then now() else completed_at end,updated_at=now() where id=v.id returning * into v; return v; end $$;
create or replace function public.quest_leaderboard(p_quest_id uuid,p_limit integer default 25) returns table(user_id uuid,xp_earned integer,progress numeric,status text) language sql security invoker as $$ select qp.user_id,qp.xp_earned,qp.progress,qp.status from public.quest_participation qp where qp.quest_id=p_quest_id order by qp.status='completed' desc,qp.xp_earned desc,qp.progress desc,qp.updated_at asc limit greatest(1,least(p_limit,100)); $$;
